import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 반려 시 마감 상태는 초기값 '신청'으로 되돌리고 동의를 비운다 (스펙에 반려 후 상태가 없음)
const REJECTED_STATUS = '신청';

function idOf(req: Request): string {
  const id = req.params['attendanceDailyId'];
  if (!/^\d+$/.test(id)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '근태 기록 ID가 올바르지 않습니다.');
  }
  return id;
}

@Controller('api/v1')
export class FnSfr03203Controller {
  @Post('/attendance-dailies/:attendanceDailyId/agree')
  @HttpCode(200)
  async agreeAttendanceDaily(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const id = idOf(req);
    const agreed = data['employeeAgreed'];
    if (typeof agreed !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '근무시간 동의 여부를 입력해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT closing_status AS "closingStatus", CAST(employee_id AS text) AS "employeeId" FROM attendance_daily WHERE attendance_daily_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_DAILY_NOT_FOUND', '대상 근태 기록이 없습니다.');
      }
      // 가정: 임직원은 본인 근무시간에만 동의할 수 있다 (사용자 ID = 임직원 ID)
      if (rows[0].employeeId !== user.id) {
        throw new ApiError(403, 'FORBIDDEN', '본인의 근무시간에만 동의할 수 있습니다.');
      }
      if (rows[0].closingStatus === '승인') {
        throw new ApiError(409, 'ATTENDANCE_ALREADY_APPROVED', '이미 승인된 건입니다. 수정하려면 승인취소 절차를 진행해 주세요.');
      }
      const updated = await db.query(
        'UPDATE attendance_daily SET employee_agreed = CAST(:agreed AS boolean), agreed_at = now(), updated_at = now() WHERE attendance_daily_id = CAST(:id AS bigint) RETURNING attendance_daily_id AS "attendanceDailyId", employee_agreed AS "employeeAgreed", closing_status AS "closingStatus"',
        { id, agreed },
      );
      return updated[0];
    });
  }

  @Post('/attendance-dailies/:attendanceDailyId/approve')
  @HttpCode(200)
  async approveAttendanceDaily(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const id = idOf(req);
    const approved = data['approved'];
    if (typeof approved !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 또는 반려를 선택해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT closing_status AS "closingStatus", employee_agreed AS "employeeAgreed" FROM attendance_daily WHERE attendance_daily_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_DAILY_NOT_FOUND', '대상 근태 기록이 없습니다.');
      }
      if (rows[0].closingStatus === '승인') {
        throw new ApiError(409, 'ATTENDANCE_ALREADY_APPROVED', '이미 승인된 건입니다. 수정하려면 승인취소 절차를 진행해 주세요.');
      }
      if (rows[0].employeeAgreed !== true) {
        throw new ApiError(422, 'EMPLOYEE_NOT_AGREED', '임직원이 근무시간에 동의하지 않았습니다.');
      }
      if (approved) {
        // 가정: 승인 시 마감 상태는 '승인'
        const done = await db.query(
          'UPDATE attendance_daily SET closing_status = :status, approver_id = CAST(:userId AS bigint), approved_at = now(), updated_at = now() WHERE attendance_daily_id = CAST(:id AS bigint) RETURNING attendance_daily_id AS "attendanceDailyId", closing_status AS "closingStatus"',
          { id, status: '승인', userId: user.id },
        );
        return done[0];
      }
      const back = await db.query(
        'UPDATE attendance_daily SET closing_status = :status, employee_agreed = NULL, agreed_at = NULL, updated_at = now() WHERE attendance_daily_id = CAST(:id AS bigint) RETURNING attendance_daily_id AS "attendanceDailyId", closing_status AS "closingStatus"',
        { id, status: REJECTED_STATUS },
      );
      return back[0];
    });
  }
}

