import { useState } from 'react';
import { Badge, Band, DataTable, DateInput, DateText, Drawer, ErrorText, Field, Filters, Form, LookupSelect, Pager, RefName, Select, Tiles, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr03203Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [message, setMessage] = useState('');
  const [agreeRow, setAgreeRow] = useState<Row | null>(null);
  const [agreeValue, setAgreeValue] = useState('');
  const [approveRow, setApproveRow] = useState<Row | null>(null);
  const [approveValue, setApproveValue] = useState('');

  const list = useData<Page>(async () => {
    if (!applied['startDate'] || !applied['endDate']) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/attendance-dailies', role, undefined, { ...applied, page, size: SIZE });
  }, [applied, page, role]);

  const rows = list.data?.items ?? [];
  const countOf = (status: string) => rows.filter((r) => r['closingStatus'] === status).length;

  function search() {
    if (!startDate || !endDate) {
      setMessage('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    setMessage('');
    setPage(0);
    setApplied({ startDate, endDate, employeeId });
  }

  function reset() {
    setStartDate('');
    setEndDate('');
    setEmployeeId('');
    setMessage('');
    setPage(0);
    setApplied({});
  }

  async function submitAgree() {
    if (!agreeRow) return;
    if (!agreeValue) {
      throw new Error('근무시간 동의 여부를 선택해 주세요.');
    }
    await call('POST', '/attendance-dailies/' + String(agreeRow['attendanceDailyId']) + '/agree', role, { employeeAgreed: agreeValue === 'Y' });
    notify('근무시간 동의를 처리했습니다.');
    setAgreeRow(null);
    setAgreeValue('');
    list.reload();
  }

  async function submitApprove() {
    if (!approveRow) return;
    if (!approveValue) {
      throw new Error('승인 또는 반려를 선택해 주세요.');
    }
    await call('POST', '/attendance-dailies/' + String(approveRow['attendanceDailyId']) + '/approve', role, { approved: approveValue === 'Y' });
    notify(approveValue === 'Y' ? '근무시간을 승인했습니다.' : '근무시간을 반려했습니다.');
    setApproveRow(null);
    setApproveValue('');
    list.reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>근태 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <span>{list.data?.total ?? 0}</span>],
            ['신청', <span>{countOf('신청')}</span>],
            ['승인', <span>{countOf('승인')}</span>],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>기간별 근태집계</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        {message ? <ErrorText text={message} /> : null}
        {list.error ? <ErrorText text={list.error} /> : null}
        <Band total={list.data?.total ?? 0} />
        <DataTable
          rows={rows}
          empty="조회된 근태 기록이 없습니다."
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'workDate', label: '근무일자', render: (r) => <DateText value={r['workDate']} /> },
            { key: 'clockInAt', label: '출근시각', render: (r) => <DateText value={r['clockInAt']} time /> },
            { key: 'clockOutAt', label: '퇴근시각', render: (r) => <DateText value={r['clockOutAt']} time /> },
            { key: 'sourceType', label: '기록 출처' },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r['closingStatus']} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span>
                  {role === '임직원' && r['closingStatus'] !== '승인' ? (
                    <button type="button" onClick={() => { setAgreeValue(''); setAgreeRow(r); }}>동의</button>
                  ) : null}
                  {role === '근태 담당자' && r['closingStatus'] !== '승인' ? (
                    <button type="button" onClick={() => { setApproveValue(''); setApproveRow(r); }}>승인·반려</button>
                  ) : null}
                </span>
              ),
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      {agreeRow ? (
        <Drawer title="근무시간 동의" onClose={() => setAgreeRow(null)}>
          <Form onSubmit={submitAgree} submit="처리">
            <Field label="근무일자">
              <DateText value={agreeRow['workDate']} />
            </Field>
            <Field label="근무시간 동의 여부" required>
              <Select value={agreeValue} onChange={setAgreeValue} options={[['Y', '동의'], ['N', '동의 안 함']]} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {approveRow ? (
        <Drawer title="근무시간 승인·반려" onClose={() => setApproveRow(null)}>
          <Form onSubmit={submitApprove} submit="처리">
            <Field label="근무일자">
              <DateText value={approveRow['workDate']} />
            </Field>
            <Field label="승인(true) 또는 반려(false)" required>
              <Select value={approveValue} onChange={setApproveValue} options={[['Y', '승인'], ['N', '반려']]} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
